def count_by(values):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return counts

def within(value, target, tolerance):
    if tolerance < 0:
        raise ValueError('tolerance must be non-negative')
    return abs(value - target) < tolerance

def extension(path):
    name = path.rsplit('/', 1)[-1]
    return name.rsplit('.', 1)[-1] if '.' in name else ''

def relative_path(path, root):
    clean_root = root.rstrip('/')
    if path == clean_root:
        return ''
    if path.startswith(clean_root):
        return path[len(clean_root):].lstrip('/')
    raise ValueError('path is outside root')

def add_parameter(query, key, value):
    separator = '&' if query else ''
    return f'{query}{separator}{key}={value}'

def replace_parameter(query, key, value):
    pairs = parse_pairs(query)
    found = False
    output = []
    for name, old_value in pairs:
        if name == key:
            if not found:
                output.append((key, value))
                found = True
        else:
            output.append((name, old_value))
    return '&'.join((f'{name}={item}' for name, item in output))

def get_nested(record, keys, default=None):
    current = record
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

def required(record, key):
    if key not in record:
        raise KeyError(key)
    return record[key]

def coerce_flag(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.lower()
        if normalized in {'true', 'yes', '1', 'on'}:
            return True
        if normalized in {'false', 'no', '0', 'off'}:
            return False
    raise ValueError('not a boolean flag')

def rename_key(record, old, new):
    result = dict(record)
    if old in result:
        result[new] = result.pop(old)
    return result

def mask_email(value):
    local, domain = value.split('@', 1)
    return local[:1] + '***@' + domain

def safe_header_value(value):
    if '\n' in value:
        raise ValueError('header value contains a line break')
    return value.strip()

def require_origin(origin, allowed):
    if origin not in allowed:
        raise PermissionError('origin is not allowed')
    return origin

def truncate_words(value, limit):
    words = value.split()
    return ' '.join(words[:limit])

def clamp_excerpt(value, limit):
    if limit <= 0:
        return ''
    if len(value) <= limit:
        return value
    return value[:limit - 3] + '...'

def format_duration(seconds):
    minutes, remainder = divmod(int(seconds), 60)
    return f'{minutes}:{remainder:02d}'

def retry_delays(attempts, base_seconds):
    if attempts < 0 or base_seconds < 0:
        raise ValueError('attempts and base_seconds must be non-negative')
    return [base_seconds * 2 ** attempt for attempt in range(attempts + 1)]
